import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import ApiService from '../../Services/ApiService';

export default function InfluencerViews() {
    const navigate = useNavigate();
    const [reelViews, setReelViews] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        loadReelViews();
    }, []);

    const loadReelViews = async () => {
        try {
            setLoading(true);
            // Fetch influencer reels to get view data
            const response = await ApiService.getInfluencerReels();
            
            if (response.success) {
                // Transform the data to show views per reel
                const viewsData = (response.data || []).map(reel => ({
                    id: reel.id,
                    title: reel.title || 'Untitled Reel',
                    thumbnail: reel.thumbnail,
                    views: reel.views || 0,
                    likes: reel.likes || 0,
                    date: reel.created_at || new Date().toISOString().split('T')[0]
                }));
                
                setReelViews(viewsData);
            } else {
                toast.error(response.message || 'Failed to load view data');
                setReelViews([]);
            }
        } catch (error) {
            console.error('Error loading view data:', error);
            toast.error('Failed to load view data: ' + (error.message || 'Unknown error'));
            setReelViews([]);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">Reel Views</h4>
                    <button 
                        className="btn btn-outline-secondary"
                        onClick={() => navigate('/studio/influencer/profile')}
                    >
                        <i className="ri-arrow-left-line me-1"></i> Back to Profile
                    </button>
                </div>
            </div>

            <div className="col-12">
                <div className="card">
                    <div className="card-body">
                        {loading ? (
                            <div className="text-center py-5">
                                <div className="spinner-border text-primary" role="status">
                                    <span className="visually-hidden">Loading...</span>
                                </div>
                                <p className="mt-2">Loading view data...</p>
                            </div>
                        ) : reelViews.length === 0 ? (
                            <div className="text-center py-5">
                                <i className="ri-bar-chart-line ri-3x text-muted"></i>
                                <h5 className="mt-3">No view data found</h5>
                                <p className="text-muted">You don't have any reels with view data yet.</p>
                            </div>
                        ) : (
                            <div className="table-responsive">
                                <table className="table table-centered table-nowrap mb-0">
                                    <thead className="table-light">
                                        <tr>
                                            <th>Reel</th>
                                            <th>Views</th>
                                            <th>Likes</th>
                                            <th>Date</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {reelViews.map((reel) => (
                                            <tr key={reel.id}>
                                                <td>
                                                    <div className="d-flex align-items-center">
                                                        {reel.thumbnail ? (
                                                            <img 
                                                                src={reel.thumbnail} 
                                                                alt={reel.title} 
                                                                className="rounded avatar-sm me-2"
                                                                style={{ objectFit: 'cover' }}
                                                            />
                                                        ) : (
                                                            <div className="avatar-sm bg-light rounded d-flex align-items-center justify-content-center me-2">
                                                                <i className="ri-image-line text-muted"></i>
                                                            </div>
                                                        )}
                                                        <div>
                                                            <h6 className="mb-0">{reel.title}</h6>
                                                        </div>
                                                    </div>
                                                </td>
                                                <td>
                                                    <h5 className="mb-0">{reel.views}</h5>
                                                </td>
                                                <td>
                                                    <h5 className="mb-0">{reel.likes}</h5>
                                                </td>
                                                <td>
                                                    <span className="text-muted">{reel.date}</span>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
